'use strict';
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare } = require('./src/semver');

assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.9', '^1.2.3'), true);
assert.equal(compare('1.10.0', '1.9.0'), 1);

// Backtracking must undo constraints of abandoned choice: a@2 requires c@2 (missing),
// a@1 requires c@1. Stale c@2 constraint previously produced null.
assert.deepEqual(resolve({
  a: { '2.0.0': { b: '*', c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
  b: { '1.0.0': {} },
  c: { '1.0.0': {} },
}, { a: '*' }), { a: '1.0.0', c: '1.0.0' });

// Later conflict backtracks to most recent choice first (b), then a.
assert.deepEqual(resolve({
  a: { '2.0.0': { c: '^2.0.0' }, '1.0.0': { c: '^1.0.0' } },
  b: { '2.0.0': { c: '^1.0.0' }, '1.0.0': { c: '^2.0.0' } },
  c: { '1.0.0': {}, '2.0.0': {} },
}, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0', c: '2.0.0' });

// Cycle.
assert.deepEqual(resolve({
  a: { '1.0.0': { b: '^1.0.0' } }, b: { '1.0.0': { a: '1.0.0' }, '1.1.0': { a: '2.0.0' } },
}, { a: '*' }), { a: '1.0.0', b: '1.0.0' });

// Missing package -> null; empty root -> {}.
assert.equal(resolve({}, { x: '*' }), null);
assert.deepEqual(resolve({}, {}), {});

// Unreachable malformed entry throws.
assert.throws(() => resolve({ z: { '1.0': {} } }, {}), TypeError);
assert.throws(() => resolve({ z: { '1.0.0': { q: '' } } }, {}), TypeError);

// Long chain, with a failure at the end forcing deep backtracking of choice frames.
const N = 50000;
const reg = {};
for (let i = 0; i < N; i += 1) reg['p' + i] = { '1.0.0': i + 1 < N ? { ['p' + (i + 1)]: '*' } : {} };
const out = resolve(reg, { p0: '*' });
assert.equal(Object.keys(out).length, N);
reg['p' + (N - 1)] = { '1.0.0': { missing: '*' } };
assert.equal(resolve(reg, { p0: '*' }), null);

// Exponential-ish: 20 packages x 2 versions; last needs impossible combo -> must prune fast.
const big = {};
for (let i = 0; i < 20; i += 1) big['q' + i] = { '1.0.0': {}, '2.0.0': {} };
big.q0 = { '1.0.0': {}, '2.0.0': { q19: '3.0.0' } };
const root = {};
for (let i = 0; i < 20; i += 1) root['q' + i] = '*';
const t = Date.now();
assert.equal(resolve(big, root).q0, '1.0.0');
assert.ok(Date.now() - t < 1000);
console.log('smoke ok');

